#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# 04-render-imageset-config.sh: generate 01-mirror/imageset-config.yaml from
# versions.env.
#
# The generated file is committed, so every change to mirrored content shows up
# as a reviewable diff (CM-3) and the high side uses the exact same file for
# disk-to-mirror.
#
# Usage: 04-render-imageset-config.sh [--check]
#   --check   don't write; exit 1 if the committed file is out of date
# -----------------------------------------------------------------------------
# shellcheck source=SCRIPTDIR/lib/common.sh
source "$(dirname "$0")/lib/common.sh"

render_packages() {
  local spec ch
  for spec in "$@"; do
    parse_operator "${spec}"
    printf '        - name: %s\n' "${OP_NAME}"
    if [[ -n "${OP_DEFAULT_CHANNEL}" ]]; then
      printf '          defaultChannel: %s\n' "${OP_DEFAULT_CHANNEL}"
    fi
    if [[ -n "${OP_CHANNELS}" ]]; then
      printf '          channels:\n'
      IFS=',' read -ra chans <<<"${OP_CHANNELS}"
      for ch in "${chans[@]}"; do
        printf '            - name: %s\n' "${ch}"
        if [[ -n "${OP_MINVERSION}" ]]; then
          printf "              minVersion: '%s'\n" "${OP_MINVERSION}"
        fi
      done
    elif [[ -n "${OP_MINVERSION}" ]]; then
      printf "          minVersion: '%s'\n" "${OP_MINVERSION}"
    fi
  done
}

render() {
  cat <<EOF
# -----------------------------------------------------------------------------
# GENERATED by 01-mirror/04-render-imageset-config.sh from versions.env.
# Do not edit by hand: change versions.env, re-render, and commit both files.
# -----------------------------------------------------------------------------
kind: ImageSetConfiguration
apiVersion: ${OC_MIRROR_API_VERSION}
EOF
  if [[ -n "${MIRROR_ARCHIVE_SIZE_GB}" ]]; then
    printf 'archiveSize: %s\n' "${MIRROR_ARCHIVE_SIZE_GB}"
  fi
  cat <<EOF
mirror:
  platform:
    architectures:
      - ${OCP_ARCH}
    channels:
      - name: ${OCP_CHANNEL}
        type: ocp
        minVersion: '${OCP_MIN_VERSION}'
        maxVersion: '${OCP_MAX_VERSION}'
    graph: ${OCP_MIRROR_GRAPH}
  operators:
    - catalog: ${OCP_OPERATOR_CATALOG}
      packages:
EOF
  render_packages "${OPERATORS[@]}"
  if ((${#CSI_OPERATORS[@]} > 0)); then
    printf '    - catalog: %s\n      packages:\n' "${CERTIFIED_OPERATOR_CATALOG}"
    render_packages "${CSI_OPERATORS[@]}"
  fi
  if ((${#ADDITIONAL_IMAGES[@]} > 0)); then
    printf '  additionalImages:\n'
    local img
    for img in "${ADDITIONAL_IMAGES[@]}"; do printf '    - name: %s\n' "${img}"; done
  fi
}

# Basic guard rails before writing anything.
[[ "${OCP_MIN_VERSION}" == "${OCP_MINOR}".* && "${OCP_MAX_VERSION}" == "${OCP_MINOR}".* ]] \
  || die "OCP_MIN_VERSION/OCP_MAX_VERSION must be ${OCP_MINOR}.z"
[[ "$(printf '%s\n%s\n' "${OCP_MIN_VERSION}" "${OCP_MAX_VERSION}" | sort -V | head -1)" == "${OCP_MIN_VERSION}" ]] \
  || die "OCP_MIN_VERSION (${OCP_MIN_VERSION}) is higher than OCP_MAX_VERSION (${OCP_MAX_VERSION})"
for img in "${ADDITIONAL_IMAGES[@]}"; do
  [[ "${img%%/*}" == *.* ]] || die "additional image needs a full registry hostname: ${img}"
done

TMP="$(mktemp)"
trap 'rm -f "${TMP}"' EXIT
render >"${TMP}"

if [[ "${1:-}" == "--check" ]]; then
  if diff -u "${IMAGESET_CONFIG}" "${TMP}"; then
    log "imageset-config.yaml is up to date"
  else
    die "imageset-config.yaml is out of date; run $(basename "$0") and commit the result"
  fi
else
  cp "${TMP}" "${IMAGESET_CONFIG}"
  chmod 0644 "${IMAGESET_CONFIG}"
  log "wrote ${IMAGESET_CONFIG}"
fi
